/* ---------- Màn hình đăng nhập (nền tối, nút "đuổi bắt": chưa nhập đủ thì nút né chuột, nhập đủ thì mở khóa) ---------- */
#gate{position:fixed;inset:0;z-index:9000;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;overflow:auto;padding:24px 16px;font-family:var(--font);color:#ecebf5;color-scheme:dark;
  background:radial-gradient(700px 480px at 50% 42%,rgba(124,92,255,.20),transparent 70%),linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px) 0 0/34px 34px,linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px) 0 0/34px 34px,#0b0b12}
#gate[hidden]{display:none}
#gate .bgimg{display:none}
#gate .top{display:flex;align-items:center;gap:12px}
#gate .logo{width:46px;height:46px;flex:none;border-radius:50%;background-color:#fff;background-image:var(--bg);background-size:cover;background-position:center;box-shadow:0 0 0 3px rgba(255,255,255,.08),0 8px 24px rgba(0,0,0,.5)}
#gate .brand{font-size:17px;font-weight:800;letter-spacing:.3px;line-height:1.15}
#gate .brand b{color:#a99bff}
#gate .brand small{display:block;font-size:10.5px;font-weight:600;letter-spacing:1.1px;color:#8d8aa6}
#gate .card{position:relative;width:min(380px,100%);padding:26px 24px 20px;border-radius:20px;border:1px solid rgba(255,255,255,.14);background:linear-gradient(180deg,rgba(32,31,46,.92),rgba(18,18,27,.94));box-shadow:0 30px 80px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.06);backdrop-filter:blur(10px)}
#gate h1{margin:0 0 6px;font-size:24px;font-weight:700;letter-spacing:-.2px;color:#fff}
#gate .hint{margin:0 0 20px;font-size:13px;line-height:1.5;color:#8d8aa6}
#gate form{width:100%;margin:0}
#gate .lb{display:flex;justify-content:space-between;align-items:center;margin:0 0 7px;font-size:12px;font-weight:600;color:#c9c7da}
#gate .lb label{display:flex;align-items:center;gap:6px;font-weight:500;color:#a99bff;cursor:pointer}
#gate .lb input{width:14px;height:14px;margin:0;accent-color:#8b74ff;cursor:pointer}
#gate .f{position:relative;height:48px;margin:0 0 16px;border:1px solid rgba(255,255,255,.12);border-radius:13px;background:rgba(8,8,14,.55);box-sizing:border-box;transition:border-color .15s,box-shadow .15s}
#gate .f:focus-within{border-color:#8b74ff;box-shadow:0 0 0 4px rgba(139,116,255,.16)}
#gate .f svg.ic{position:absolute;left:14px;top:50%;transform:translateY(-50%);width:17px;height:17px;color:#8d8aa6}
#gate .f input{position:absolute;left:40px;top:0;width:calc(100% - 78px);height:46px;box-sizing:border-box;border:0;background:transparent;outline:none;font:14.5px var(--font);color:#fff;padding:0 4px}
#gate .f2 input{width:calc(100% - 110px)}
#gate .f input::placeholder{color:#6d6a86}
#gate .f input:-webkit-autofill{-webkit-text-fill-color:#fff;transition:background-color 9999s}
#gate .tick{position:absolute;right:12px;top:50%;width:20px;height:20px;margin-top:-10px;border-radius:50%;background:#8b74ff;color:#fff;display:grid;place-items:center;transform:scale(0);transition:transform .25s cubic-bezier(.3,1.6,.5,1)}
#gate .tick svg{width:12px;height:12px}
#gate .f.ok .tick{transform:scale(1)}
#gate .eye{position:absolute;right:38px;top:7px;width:32px;height:32px;border:0;background:none;color:#8d8aa6;cursor:pointer;display:grid;place-items:center;padding:0;border-radius:8px}
#gate .eye:hover{background:rgba(255,255,255,.06);color:#fff}
#gate .eye svg{width:18px;height:18px}
#gate #gS{display:none}
#gate .dock{position:relative;height:60px;margin:6px 0 0;border-radius:30px;background:#07070c;border:1px solid rgba(255,255,255,.07);box-shadow:inset 0 2px 10px rgba(0,0,0,.7);overflow:hidden;touch-action:manipulation}
#gate .socket{position:absolute;left:14px;top:50%;width:10px;height:10px;margin-top:-5px;border-radius:50%;background:#2a2838;box-shadow:0 0 0 3px rgba(139,116,255,.15);transition:background .3s,box-shadow .3s}
#gate .tether{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
#gate .tether line{stroke:rgba(139,116,255,.45);stroke-width:1.5;stroke-dasharray:3 4}
#gate .tether circle{fill:#8b74ff}
#gate .cta{position:absolute;left:0;top:8px;width:150px;height:42px;border:0;border-radius:21px;background:linear-gradient(180deg,#9a86ff,#7458f0);color:#fff;font:600 14px var(--font);cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;box-shadow:0 6px 22px rgba(124,92,255,.45);transition:transform .34s cubic-bezier(.25,1.3,.5,1),box-shadow .2s,filter .2s;will-change:transform}
#gate .dock:not(.on) .cta{filter:saturate(.55) brightness(.85)}
#gate .dock.on .cta{box-shadow:0 0 0 4px rgba(139,116,255,.18),0 8px 30px rgba(124,92,255,.65)}
#gate .dock.on .socket{background:#8b74ff;box-shadow:0 0 12px #8b74ff}
#gate .dock.on .tether line{stroke:#8b74ff;stroke-dasharray:none}
#gate .cta:active{filter:brightness(1.1)}
#gate .cta .spin{display:none;width:15px;height:15px;border:2px solid rgba(255,255,255,.35);border-top-color:#fff;border-radius:50%;animation:gspin .7s linear infinite}
#gate .cta:disabled{cursor:wait}
#gate .cta:disabled .spin{display:block}
@keyframes gspin{to{transform:rotate(360deg)}}
#gate .dock.shake{animation:gshake .4s}
@keyframes gshake{20%,60%{transform:translateX(-6px)}40%,80%{transform:translateX(6px)}}
#gate .err{min-height:18px;margin-top:12px;text-align:center;font-size:13px;color:#ff8fa3}
#gate .gf{margin-top:6px;font-size:12px;color:#6d6a86;text-align:center}
#gate .gf b{color:#a99bff;font-weight:600}
@media (prefers-reduced-motion:reduce){#gate .cta{transition:none}}

